const payload = $input.first().json.body ?? $input.first().json;
const action = payload.action;

const eventType = payload.issue
  ? (payload.pull_request ? 'pull_request' : 'issue')
  : payload.pull_request
    ? 'pull_request'
    : 'unknown';

const validActions = {
  issue: ['opened', 'edited', 'reopened'],
  pull_request: ['opened', 'synchronize', 'reopened', 'edited']
};

if (!validActions[eventType]?.includes(action)) {
  return [];
}

const repo = payload.repository;
const owner = repo.owner.login;
const repoName = repo.name;
const defaultBranch = repo.default_branch || 'main';

let number, title, description, htmlUrl, labels;
if (eventType === 'issue') {
  number = payload.issue.number;
  title = payload.issue.title;
  description = payload.issue.body || '';
  htmlUrl = payload.issue.html_url;
  labels = (payload.issue.labels || []).map((l) => l.name).join(', ');
} else {
  number = payload.pull_request.number;
  title = payload.pull_request.title;
  description = payload.pull_request.body || '';
  htmlUrl = payload.pull_request.html_url;
  labels = '';
}

const fetch_type = eventType === 'pull_request' ? 'pr_files' : 'file';
let file_path = 'README.md';
const pathMatches = (description || '').match(/[\w./-]+\.(md|json|yml|yaml|ts|tsx|js|py|go|sh)\b/g);
if (pathMatches && pathMatches.length) {
  file_path = pathMatches[0];
}

return [{
  json: {
    eventType,
    action,
    owner,
    repo: repoName,
    number,
    title,
    description,
    htmlUrl,
    defaultBranch,
    labels,
    fetch_type,
    file_path
  }
}];

const event = $('Parse GitHub Event').first().json;
let response = '';

if (event.fetch_type === 'pr_files') {
  const files = $input.all().map((item) => item.json).filter((file) => file.filename);
  const lines = files.map((file) => [
    '- ' + file.filename,
    '  status: ' + file.status,
    '  changes: +' + file.additions + ' / -' + file.deletions,
    file.patch ? '  patch preview:\n' + file.patch.slice(0, 1500) : '  (no patch in response)',
  ].join('\n'));
  response = [
    '## Pull Request Changed Files',
    'Repo: ' + event.owner + '/' + event.repo,
    'PR #' + event.number,
    '',
    lines.join('\n\n') || '(no files returned)',
  ].join('\n');
} else {
  const item = $input.first().json;
  let content = '';
  if (item.content && item.encoding === 'base64') {
    content = Buffer.from(item.content, 'base64').toString('utf8');
  } else {
    content = JSON.stringify(item, null, 2);
  }
  response = [
    '## File: ' + event.file_path,
    'Repo: ' + event.owner + '/' + event.repo,
    'Ref: ' + event.defaultBranch,
    '',
    content.slice(0, 12000),
  ].join('\n');
}

return [{ json: { response } }];

const event = $('Parse GitHub Event').first().json;
const codeText = $('Format Code Response').first().json.response || '';

const archText = $('Read Architecture Docs').all().map((item) => {
  const name = item.json.fileName || item.binary?.data?.fileName || 'architecture.md';
  const b64 = item.binary?.data?.data;
  const text = b64 ? Buffer.from(b64, 'base64').toString('utf8') : '';
  return '### ' + name + '\n' + text;
}).join('\n\n---\n\n') || '(No architecture docs at /data/architecture — add markdown files to improve-codebase-architecture/)';

const userContent = [
  'Triaging GitHub ' + event.eventType.replace('_', ' ') + ' #' + event.number,
  'Repository: ' + event.owner + '/' + event.repo,
  'URL: ' + event.htmlUrl,
  'Action: ' + event.action,
  '',
  '## Title',
  event.title,
  '',
  '## Description',
  event.description || '(no description provided)',
  event.labels ? '## Labels\n' + event.labels : '',
  '',
  '## Code from repository',
  codeText.slice(0, 12000),
  '',
  '## Architecture guidelines',
  archText.slice(0, 8000),
  '',
  'Write ONLY a GitHub comment body in markdown with these exact sections:',
  '## Root Cause Analysis',
  '## Suggested Fix (include a fenced code block)',
  '## Architecture Compliance (bullet with Score X/100 and Notes)',
  '## Recommended Next Steps',
  'End with: _Posted by Code Companion (local Ollama)_'
].filter(Boolean).join('\n');

if (!userContent || userContent.length < 100) {
  throw new Error('Triage prompt is empty. Check Fetch GitHub Content and Read Architecture Docs outputs.');
}

const ollamaResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ollama:11434/api/chat',
  body: {
    model: 'qwen2.5-coder:7b',
    stream: false,
    options: { temperature: 0.2, num_predict: -1 },
    messages: [
      {
        role: 'system',
        content: 'You are a staff engineer triaging GitHub issues and pull requests. Use the provided code and architecture guidelines. Output ONLY the markdown comment body — never JSON, never tool calls, never meta-commentary about the prompt.',
      },
      { role: 'user', content: userContent },
    ],
  },
  json: true,
  timeout: 300000,
});

const triageBody = ollamaResponse?.message?.content || '';
if (!triageBody || triageBody.length < 80) {
  throw new Error('Ollama returned an empty or too-short triage comment.');
}

return [{ json: { ...event, triageBody } }];

const event = $input.first().json;
let body = event.triageBody || '';

if (typeof body !== 'string') {
  body = JSON.stringify(body, null, 2);
}

const trimmed = body.trim();

if (trimmed.startsWith('{') && trimmed.includes('"name"') && trimmed.includes('"arguments"')) {
  throw new Error('Model returned tool-call JSON instead of markdown. Try qwen3:8b or llama3.2.');
}

if (!trimmed || trimmed.length < 80) {
  throw new Error('Triage output too short. Check Ollama logs and Build Triage Prompt output.');
}

if (!trimmed.includes('## Root Cause Analysis')) {
  body = '## Root Cause Analysis\n' + body;
}

const header = '> Code Companion triage for **#' + event.number + '** — ' + event.htmlUrl + '\n\n';

return [{
  json: {
    owner: event.owner,
    repo: event.repo,
    number: event.number,
    commentBody: header + body.trim()
  }
}];
